create or replace function public.get_hr_employee_detail_v1(p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint,p_employment_id bigint) returns jsonb language plpgsql stable set search_path to '' as $fn$
declare v_membership bigint;v_can_manage boolean:=false;v_detail jsonb;v_attendance jsonb;v_leave jsonb;
begin
select m.id,exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.manage') into v_membership,v_can_manage from public.memberships m where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active' and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id)) and exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='hr.employee.read') order by m.created_at limit 1;
if v_membership is null then raise exception 'employee read permission denied'; end if;
select jsonb_build_object('employment_id',e.id,'person_id',e.employee_person_id,'employee_number',e.employee_number,'display_name',p.display_name,'name_native',p.name_native,'gender',p.gender,'preferred_locale',p.preferred_locale,'department_key',e.department_key,'designation_key',e.designation_key,'designation',ep.designation,'contract_type',e.contract_type,'starts_on',e.starts_on,'ends_on',e.ends_on,'payroll_eligible',e.payroll_eligible,'state',e.state,'qualification_summary',ep.qualification_summary,'profile_status',ep.status) into v_detail from public.hr_employments e join public.employee_profiles ep on ep.tenant_id=e.tenant_id and ep.person_id=e.employee_person_id join public.persons p on p.tenant_id=e.tenant_id and p.id=e.employee_person_id where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and e.id=p_employment_id;
if v_detail is null then raise exception 'employee not found in active branch'; end if;
select coalesce(jsonb_agg(to_jsonb(x) order by x.attendance_date desc),'[]'::jsonb) into v_attendance from (select a.attendance_date,a.status,a.check_in_at,a.check_out_at,a.source,a.latest_correction_id,a.correction_reason from public.hr_effective_attendance_v1 a where a.tenant_id=p_tenant_id and a.employment_id=p_employment_id order by a.attendance_date desc limit 30) x;
select coalesce(jsonb_agg(to_jsonb(x) order by x.starts_on desc,x.id desc),'[]'::jsonb) into v_leave from (select lr.id,lr.starts_on,lr.ends_on,lr.requested_units,lr.reason,lr.state,lr.decided_at,lr.decision_reason,lt.key leave_type_key,lt.labels leave_type_labels,lt.payroll_effect from public.hr_leave_requests lr join public.hr_leave_types lt on lt.tenant_id=lr.tenant_id and lt.id=lr.leave_type_id where lr.tenant_id=p_tenant_id and lr.employment_id=p_employment_id order by lr.starts_on desc,lr.id desc limit 30) x;
return jsonb_build_object('employee',v_detail,'attendance',v_attendance,'leave',v_leave,'can_manage',v_can_manage);end;$fn$;
revoke all on function public.get_hr_employee_detail_v1(uuid,bigint,bigint,bigint) from public,anon,authenticated;
grant execute on function public.get_hr_employee_detail_v1(uuid,bigint,bigint,bigint) to service_role;